(function(){
'use strict';
var STATE_KEY='welog-pair-sheet-v4';
function readState(){try{return JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}}catch(e){return{}}}
async function waitReady(sheet){if(document.fonts){try{await document.fonts.ready}catch(e){}}var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
function hideEditorOverlays(sheet){var list=[].slice.call(sheet.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.st-v2-lock,.st-v2-del,.st-v2-resize,.direct-crop-ui,.guide-line'));var prev=list.map(function(el){return{el:el,visibility:el.style.visibility}});list.forEach(function(el){el.style.setProperty('visibility','hidden','important')});return function(){prev.forEach(function(x){x.el.style.visibility=x.visibility})}}
function visibleBounds(sheet){var sr=sheet.getBoundingClientRect(),left=sr.left,top=sr.top,right=sr.right,bottom=sr.bottom;sheet.querySelectorAll('*').forEach(function(el){var cs=getComputedStyle(el);if(cs.display==='none'||cs.visibility==='hidden'||parseFloat(cs.opacity||'1')===0)return;var r=el.getBoundingClientRect();if(!isFinite(r.left)||!isFinite(r.top)||r.width===0&&r.height===0)return;left=Math.min(left,r.left);top=Math.min(top,r.top);right=Math.max(right,r.right);bottom=Math.max(bottom,r.bottom)});var pad=2;return{x:Math.floor(left+window.scrollX-pad),y:Math.floor(top+window.scrollY-pad),width:Math.ceil(right-left+pad*2),height:Math.ceil(bottom-top+pad*2)}}
function downloadBlob(blob,name){var u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name+'.png';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},1500)}
async function canvasBlob(canvas){return await new Promise(function(res,rej){try{canvas.toBlob(function(b){b?res(b):rej(new Error('PNG blob creation failed'))},'image/png')}catch(e){rej(e)}})}
async function captureFullVisual(sheet){if(!window.html2canvas)throw new Error('html2canvas unavailable');var b=visibleBounds(sheet);return await window.html2canvas(document.body,{scale:Math.max(2,window.devicePixelRatio||1),useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,foreignObjectRendering:false,removeContainer:true,x:b.x,y:b.y,width:b.width,height:b.height,windowWidth:Math.max(document.documentElement.scrollWidth,window.innerWidth),windowHeight:Math.max(document.documentElement.scrollHeight,window.innerHeight),ignoreElements:function(el){return el!==sheet&&!sheet.contains(el)&&(el.closest&&el.closest('.inspector,.topbar,.slot-drawer,.image-modal,.welog-fit-preview'))}})}
async function captureFallback(sheet){if(!window.htmlToImage||!window.htmlToImage.toPng)throw new Error('html-to-image unavailable');var b=visibleBounds(sheet),sr=sheet.getBoundingClientRect(),extraRight=Math.max(0,(b.x-window.scrollX+b.width)-sr.right),extraBottom=Math.max(0,(b.y-window.scrollY+b.height)-sr.bottom),w=Math.ceil(sr.width+extraRight),h=Math.ceil(sr.height+extraBottom);var old={overflow:sheet.style.overflow,width:sheet.style.width,height:sheet.style.height,minHeight:sheet.style.minHeight};sheet.style.setProperty('overflow','visible','important');sheet.style.setProperty('width',w+'px','important');sheet.style.setProperty('height',h+'px','important');sheet.style.setProperty('min-height',h+'px','important');try{var url=await window.htmlToImage.toPng(sheet,{pixelRatio:Math.max(2,window.devicePixelRatio||1),cacheBust:true,backgroundColor:null,skipAutoScale:false,width:w,height:h});var resp=await fetch(url);if(!resp.ok)throw new Error('fallback image conversion failed');return await resp.blob()}finally{sheet.style.overflow=old.overflow;sheet.style.width=old.width;sheet.style.height=old.height;sheet.style.minHeight=old.minHeight}}
async function saveLive(){var sheet=document.getElementById('sheet'),btn=document.getElementById('printBtn');if(!sheet||!btn)return;var old=btn.textContent,restoreOverlay=function(){};btn.disabled=true;btn.textContent='저장 중…';try{await waitReady(sheet);restoreOverlay=hideEditorOverlays(sheet);await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var blob;try{var canvas=await captureFullVisual(sheet);blob=await canvasBlob(canvas)}catch(firstError){console.warn('full visual capture failed; trying fallback',firstError);blob=await captureFallback(sheet)}var name=((readState().pairName||'WeLog').trim()||'WeLog');downloadBlob(blob,name)}catch(e){console.error('live sheet save failed',e);alert('PNG 저장에 실패했습니다. 다시 시도해 주세요.')}finally{try{restoreOverlay()}catch(e){}btn.disabled=false;btn.textContent=old}}
function install(){var old=document.getElementById('printBtn');if(!old)return;var b=old.cloneNode(true);b.dataset.liveSaveReady='5';old.replaceWith(b);b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();saveLive()},true)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();setTimeout(install,500);
})();